impl Solution {
    pub fn lost_permutation(b: Vec<u32>, m: usize, s: u32) -> bool {
        let mut found = b.clone();
        found.sort();
        let mut missing_sum = s;
        let mut next_num = 1u32;

        for &num in &found {
            while next_num < num {
                missing_sum -= next_num;
                if missing_sum < 0 {
                    return false;
                }
                next_num += 1;
            }
            next_num += 1;
        }

        while missing_sum > 0 {
            missing_sum -= next_num;
            if missing_sum < 0 {
                return false;
            }
            next_num += 1;
        }

        missing_sum == 0
    }
}

